import sys

def can_form_sequence(a):
    s = set(a)
    for x in a:
        for y in a:
            if x - y in s:
                break
        else:
            return False
    return True

input = sys.stdin.read().strip().split()
t = int(input[0])
index = 1
results = []

for _ in range(t):
    n = int(input[index])
    a = list(map(int, input[index+1:index+1+n]))
    index += 1 + n
    results.append("YES" if can_form_sequence(a) else "NO")

print("\n".join(results))
